    camp := camp || jsonb_build_object('c3', new_id);
    VALUES ('system', NULL, NULL, 'single', $t$Năm 1258, đạo quân Mông Cổ xâm lược Đại Việt do ai chỉ huy?$t$, $t$Tháng 1/1258, tướng Ngột Lương Hợp Thai chỉ huy khoảng 3 vạn quân Mông Cổ tiến vào Đại Việt.$t$, 1, (camp->>'c1')::integer, $j${"options":[{"id":"a","text":"Thoát Hoan"},{"id":"b","text":"Ngột Lương Hợp Thai"},{"id":"c","text":"Toa Đô"},{"id":"d","text":"Ô Mã Nhi"}],"correct":"b"}$j$::jsonb, $t$nam 1258, dao quan mong co xam luoc dai viet do ai chi huy? thang 1/1258, tuong ngot luong hop thai chi huy khoang 3 van quan mong co tien vao dai viet. a thoat hoan b ngot luong hop thai c toa do d o ma nhi b$t$) RETURNING id INTO new_id;
    qs := qs || jsonb_build_object('c1_chi_huy', new_id);
    VALUES ('system', NULL, NULL, 'single', $t$Trận phản công thắng lợi kết thúc cuộc kháng chiến lần thứ nhất diễn ra ở đâu?$t$, $t$Ngày 29/1/1258, quân Trần phản công thắng lợi tại Đông Bộ Đầu, quét sạch giặc khỏi bờ cõi.$t$, 1, (camp->>'c1')::integer, $j${"options":[{"id":"a","text":"Bạch Đằng"},{"id":"b","text":"Hàm Tử"},{"id":"c","text":"Đông Bộ Đầu"},{"id":"d","text":"Chương Dương"}],"correct":"c"}$j$::jsonb, $t$tran phan cong thang loi ket thuc cuoc khang chien lan thu nhat dien ra o dau? ngay 29/1/1258, quan tran phan cong thang loi tai dong bo dau, quet sach giac khoi bo coi. a bach dang b ham tu c dong bo dau d chuong duong c$t$) RETURNING id INTO new_id;
    qs := qs || jsonb_build_object('c1_thang_loi', new_id);
    VALUES ('system', NULL, NULL, 'truefalse', $t$Để bảo toàn lực lượng, vua tôi nhà Trần rời Thăng Long và thực hiện kế "Vườn không nhà trống".$t$, $t$Nhà Trần đem dân, của đi nơi khác để giặc không cướp được lương thực, khiến quân Mông Cổ vào Thăng Long chỉ thấy kinh thành trống không.$t$, 1, (camp->>'c1')::integer, $j${"correct":true}$j$::jsonb, $t$de bao toan luc luong, vua toi nha tran roi thang long va thuc hien ke "vuon khong nha trong". nha tran dem dan, cua di noi khac de giac khong cuop duoc luong thuc, khien quan mong co vao thang long chi thay kinh thanh trong khong. true$t$) RETURNING id INTO new_id;
