    qs := qs || jsonb_build_object('c1_dien', new_id);
    VALUES ('system', NULL, NULL, 'order', $t$Sắp xếp các sự kiện của cuộc kháng chiến lần thứ nhất theo thứ tự thời gian.$t$, $t$Quân Trần lui để bảo toàn lực lượng, đợi giặc thiếu lương, mệt mỏi rồi mới phản công.$t$, 2, (camp->>'c1')::integer, $j${"items":[{"id":"a","text":"Quân Mông Cổ tiến vào Đại Việt"},{"id":"b","text":"Quân Trần chặn giặc ở Bình Lệ Nguyên rồi rút lui"},{"id":"c","text":"Triều đình rời Thăng Long, thực hiện \"Vườn không nhà trống\""},{"id":"d","text":"Quân Trần phản công thắng lợi ở Đông Bộ Đầu"}]}$j$::jsonb, $t$sap xep cac su kien cua cuoc khang chien lan thu nhat theo thu tu thoi gian. quan tran lui de bao toan luc luong, doi giac thieu luong, met moi roi moi phan cong. a quan mong co tien vao dai viet b quan tran chan giac o binh le nguyen roi rut lui c trieu dinh roi thang long thuc hien \ vuon khong nha trong\ d quan tran phan cong thang loi o dong bo dau$t$) RETURNING id INTO new_id;
