    qs := qs || jsonb_build_object('c1_kiem_tra_1', new_id);
    VALUES ('system', NULL, NULL, 'single', $t$Kế sách "Vườn không nhà trống" nhằm mục đích chính nào?$t$, $t$Không để giặc cướp được lương thực, khiến chúng nhanh suy yếu.$t$, 2, (camp->>'c1')::integer, $j${"options":[{"id":"a","text":"Làm quân giặc thiếu lương thực và mệt mỏi"},{"id":"b","text":"Xây thêm thành lũy ở Thăng Long"},{"id":"c","text":"Mở rộng lãnh thổ ra phía Bắc"},{"id":"d","text":"Xin giảng hòa với quân Mông Cổ"}],"correct":"a"}$j$::jsonb, $t$ke sach "vuon khong nha trong" nham muc dich chinh nao? khong de giac cuop duoc luong thuc, khien chung nhanh suy yeu. a lam quan giac thieu luong thuc va met moi b xay them thanh luy o thang long c mo rong lanh tho ra phia bac d xin giang hoa voi quan mong co a$t$) RETURNING id INTO new_id;
    qs := qs || jsonb_build_object('c1_kiem_tra_2', new_id);
