    qs := qs || jsonb_build_object('c2_dien_hong', new_id);
    VALUES ('system', NULL, NULL, 'multiple', $t$Những địa danh nào gắn với các chiến thắng của quân Trần mùa hè năm 1285?$t$, $t$Tháng 5 – 6/1285 quân Trần thắng ở Tây Kết, Hàm Tử, Chương Dương và giải phóng Thăng Long. Bạch Đằng và Vân Đồn thuộc cuộc kháng chiến lần III.$t$, 2, (camp->>'c2')::integer, $j${"options":[{"id":"a","text":"Tây Kết"},{"id":"b","text":"Hàm Tử"},{"id":"c","text":"Chương Dương"},{"id":"d","text":"Bạch Đằng"},{"id":"e","text":"Vân Đồn"}],"correct":["a","b","c"]}$j$::jsonb, $t$nhung dia danh nao gan voi cac chien thang cua quan tran mua he nam 1285? thang 5 – 6/1285 quan tran thang o tay ket, ham tu, chuong duong va giai phong thang long. bach dang va van don thuoc cuoc khang chien lan iii. a tay ket b ham tu c chuong duong d bach dang e van don a b c$t$) RETURNING id INTO new_id;
    qs := qs || jsonb_build_object('c2_dia_danh', new_id);
    VALUES ('system', NULL, NULL, 'truefalse', $t$Khi bị bắt và bị dụ hàng, Trần Bình Trọng nói: "Ta thà làm quỷ nước Nam, chứ không thèm làm vương đất Bắc!"$t$, $t$Ông không khuất phục và hy sinh khi mới 26 tuổi.$t$, 1, (camp->>'c2')::integer, $j${"correct":true}$j$::jsonb, $t$khi bi bat va bi du hang, tran binh trong noi: "ta tha lam quy nuoc nam, chu khong them lam vuong dat bac!" ong khong khuat phuc va hy sinh khi moi 26 tuoi. true$t$) RETURNING id INTO new_id;
    qs := qs || jsonb_build_object('c2_binh_trong', new_id);
