    qs := qs || jsonb_build_object('c2_toa_do', new_id);
    VALUES ('system', NULL, NULL, 'order', $t$Sắp xếp các sự kiện sau theo thứ tự thời gian.$t$, $t$Từ Bình Than đến Chương Dương, nhà Trần chuẩn bị rồi rút lui bảo toàn lực lượng và phản công.$t$, 3, (camp->>'c2')::integer, $j${"items":[{"id":"a","text":"Hội nghị Bình Than (1282)"},{"id":"b","text":"Trần Quốc Tuấn được phong Quốc công Tiết chế (1283)"},{"id":"c","text":"Trần Bình Trọng chặn quân Nguyên ở Đà Mạc (đầu 1285)"},{"id":"d","text":"Chiến thắng Chương Dương, giải phóng Thăng Long (1285)"}]}$j$::jsonb, $t$sap xep cac su kien sau theo thu tu thoi gian. tu binh than den chuong duong, nha tran chuan bi roi rut lui bao toan luc luong va phan cong. a hoi nghi binh than (1282) b tran quoc tuan duoc phong quoc cong tiet che (1283) c tran binh trong chan quan nguyen o da mac (dau 1285) d chien thang chuong duong giai phong thang long (1285)$t$) RETURNING id INTO new_id;
