    VALUES ('system', NULL, NULL, 'single', $t$Thoát Hoan phải trốn về nước năm 1285 bằng cách nào?$t$, $t$Theo sử sách, Thoát Hoan chui vào ống đồng đặt trên xe để tránh tên tẩm thuốc độc của quân Trần.$t$, 2, (camp->>'c2')::integer, $j${"options":[{"id":"a","text":"Cưỡi voi chiến vượt biên giới"},{"id":"b","text":"Chui vào ống đồng cho lính kéo đi"},{"id":"c","text":"Cải trang làm thương nhân"},{"id":"d","text":"Xin giặc Tống mở đường"}],"correct":"b"}$j$::jsonb, $t$thoat hoan phai tron ve nuoc nam 1285 bang cach nao? theo su sach, thoat hoan chui vao ong dong dat tren xe de tranh ten tam thuoc doc cua quan tran. a cuoi voi chien vuot bien gioi b chui vao ong dong cho linh keo di c cai trang lam thuong nhan d xin giac tong mo duong b$t$) RETURNING id INTO new_id;
