    qs := qs || jsonb_build_object('c3_coc', new_id);
    VALUES ('system', NULL, NULL, 'fill', $t$Chiến thắng Bạch Đằng lịch sử diễn ra vào năm ____.$t$, $t$Tháng 4/1288, quân Nguyên thất bại hoàn toàn ở Bạch Đằng.$t$, 1, (camp->>'c3')::integer, $j${"blanks":[{"accept":["1288"]}]}$j$::jsonb, $t$chien thang bach dang lich su dien ra vao nam ____. thang 4/1288, quan nguyen that bai hoan toan o bach dang. 1288$t$) RETURNING id INTO new_id;
