    qs := qs || jsonb_build_object('c3_bat_song', new_id);
    VALUES ('system', NULL, NULL, 'single', $t$Tác phẩm "Hịch tướng sĩ" do ai soạn?$t$, $t$Trần Quốc Tuấn soạn Hịch tướng sĩ để khích lệ tướng sĩ quyết tâm chống giặc.$t$, 1, (camp->>'c3')::integer, $j${"options":[{"id":"a","text":"Trần Nhân Tông"},{"id":"b","text":"Trần Quang Khải"},{"id":"c","text":"Trần Quốc Tuấn (Trần Hưng Đạo)"},{"id":"d","text":"Phạm Ngũ Lão"}],"correct":"c"}$j$::jsonb, $t$tac pham "hich tuong si" do ai soan? tran quoc tuan soan hich tuong si de khich le tuong si quyet tam chong giac. a tran nhan tong b tran quang khai c tran quoc tuan (tran hung dao) d pham ngu lao c$t$) RETURNING id INTO new_id;
    qs := qs || jsonb_build_object('c3_hich', new_id);
    VALUES ('system', NULL, NULL, 'order', $t$Sắp xếp các sự kiện của cuộc kháng chiến lần thứ ba theo thứ tự thời gian.$t$, $t$Mất đường tiếp tế vì Vân Đồn, quân Nguyên phải rút lui rồi bị chặn đánh ở Bạch Đằng.$t$, 3, (camp->>'c3')::integer, $j${"items":[{"id":"a","text":"Quân Nguyên tiến vào Đại Việt (cuối 1287)"},{"id":"b","text":"Trần Khánh Dư đánh tan đoàn thuyền lương ở Vân Đồn (đầu 1288)"},{"id":"c","text":"Quân Nguyên rút khỏi Thăng Long (xuân 1288)"},{"id":"d","text":"Chiến thắng Bạch Đằng (tháng 4/1288)"}]}$j$::jsonb, $t$sap xep cac su kien cua cuoc khang chien lan thu ba theo thu tu thoi gian. mat duong tiep te vi van don, quan nguyen phai rut lui roi bi chan danh o bach dang. a quan nguyen tien vao dai viet (cuoi 1287) b tran khanh du danh tan doan thuyen luong o van don (dau 1288) c quan nguyen rut khoi thang long (xuan 1288) d chien thang bach dang (thang 4/1288)$t$) RETURNING id INTO new_id;
    qs := qs || jsonb_build_object('c3_thu_tu', new_id);
    VALUES ('system', NULL, NULL, 'map', $t$Kéo các địa danh lên đúng vị trí trên bản đồ.$t$, $t$Vân Đồn ở vùng biển Quảng Ninh; sông Bạch Đằng đổ ra cửa biển giữa Quảng Ninh và Hải Phòng.$t$, 3, (camp->>'c3')::integer, $j${"targets":[{"id":"a","label":"Thăng Long (Hà Nội)","lat":21.03,"lng":105.85,"radius_km":25},{"id":"b","label":"Vân Đồn (Quảng Ninh)","lat":21.06,"lng":107.43,"radius_km":35},{"id":"c","label":"Sông Bạch Đằng (Quảng Ninh – Hải Phòng)","lat":20.95,"lng":106.8,"radius_km":35}]}$j$::jsonb, $t$keo cac dia danh len dung vi tri tren ban do. van don o vung bien quang ninh; song bach dang do ra cua bien giua quang ninh va hai phong. a thang long (ha noi) 21.03 105.85 25 b van don (quang ninh) 21.06 107.43 35 c song bach dang (quang ninh – hai phong) 20.95 106.8 35$t$) RETURNING id INTO new_id;
    qs := qs || jsonb_build_object('c3_ban_do', new_id);
    VALUES ('system', NULL, NULL, 'single', $t$Chiến thắng Vân Đồn có ý nghĩa gì đối với quân Nguyên?$t$, $t$Đoàn thuyền lương bị đánh tan khiến quân Nguyên thiếu lương, buộc phải rút lui.$t$, 2, (camp->>'c3')::integer, $j${"options":[{"id":"a","text":"Quân Nguyên mất nguồn lương thực tiếp tế"},{"id":"b","text":"Quân Nguyên chiếm được Thăng Long"},{"id":"c","text":"Quân Nguyên có thêm viện binh"},{"id":"d","text":"Quân Nguyên được nghỉ ngơi"}],"correct":"a"}$j$::jsonb, $t$chien thang van don co y nghia gi doi voi quan nguyen? doan thuyen luong bi danh tan khien quan nguyen thieu luong, buoc phai rut lui. a quan nguyen mat nguon luong thuc tiep te b quan nguyen chiem duoc thang long c quan nguyen co them vien binh d quan nguyen duoc nghi ngoi a$t$) RETURNING id INTO new_id;
    qs := qs || jsonb_build_object('c3_kiem_tra_1', new_id);
    VALUES ('system', NULL, NULL, 'truefalse', $t$Kháng chiến chống Nguyên lần thứ ba kết thúc bằng thắng lợi của nhà Trần.$t$, $t$Chiến thắng Bạch Đằng đập tan hoàn toàn mộng xâm lăng của nhà Nguyên.$t$, 1, (camp->>'c3')::integer, $j${"correct":true}$j$::jsonb, $t$khang chien chong nguyen lan thu ba ket thuc bang thang loi cua nha tran. chien thang bach dang dap tan hoan toan mong xam lang cua nha nguyen. true$t$) RETURNING id INTO new_id;
    qs := qs || jsonb_build_object('c3_kiem_tra_2', new_id);
    VALUES ('system', NULL, NULL, $t$Lần I – Bình Lệ Nguyên và kế "Vườn không nhà trống"$t$, $t$Ôn tập nhanh về cách nhà Trần ứng phó với quân Mông Cổ năm 1258.$t$, (camp->>'c1')::integer, 20, false, false, 60, $t$lan i – binh le nguyen va ke "vuon khong nha trong" on tap nhanh ve cach nha tran ung pho voi quan mong co nam 1258.$t$) RETURNING id INTO new_id;
