    zs := zs || jsonb_build_object('z1_dong_bo_dau', new_id);
    VALUES ('system', NULL, NULL, $t$Quyết chiến Lần I (1258)$t$, $t$Bài tổng kết cuộc kháng chiến chống Mông Cổ lần thứ nhất.$t$, (camp->>'c1')::integer, 25, true, true, 70, $t$quyet chien lan i (1258) bai tong ket cuoc khang chien chong mong co lan thu nhat.$t$) RETURNING id INTO new_id;
    zs := zs || jsonb_build_object('z1_final', new_id);
    VALUES ('system', NULL, NULL, $t$Lần II – Chuẩn bị kháng chiến và trận Đà Mạc$t$, $t$Bình Than, Diên Hồng, Tiết chế và tấm gương Trần Bình Trọng.$t$, (camp->>'c2')::integer, 20, false, false, 60, $t$lan ii – chuan bi khang chien va tran da mac binh than, dien hong, tiet che va tam guong tran binh trong.$t$) RETURNING id INTO new_id;
