    zs := zs || jsonb_build_object('z3_bach_dang', new_id);
    VALUES ('system', NULL, NULL, $t$Quyết chiến Lần III (1287 – 1288)$t$, $t$Bài tổng kết cuộc kháng chiến chống Nguyên lần thứ ba.$t$, (camp->>'c3')::integer, 30, true, true, 70, $t$quyet chien lan iii (1287 – 1288) bai tong ket cuoc khang chien chong nguyen lan thu ba.$t$) RETURNING id INTO new_id;
    zs := zs || jsonb_build_object('z3_final', new_id);
    VALUES ($t$Kháng chiến chống Mông Cổ lần thứ nhất (1258)$t$, $t$Vì sao nhà Trần chọn lui để bảo toàn lực lượng rồi mới phản công?$t$, (camp->>'c1')::integer, $j$[{"type":"text","heading":"Bối cảnh","text":"Đầu năm 1258, khoảng 3 vạn quân Mông Cổ do tướng Ngột Lương Hợp Thai chỉ huy tiến vào Đại Việt. Lúc này nhà Trần do vua Trần Thái Tông đứng đầu, Thái sư Trần Thủ Độ giúp việc triều chính."},{"type":"text","heading":"Diễn biến","text":"Quân Trần chặn giặc ở Bình Lệ Nguyên nhưng thế giặc mạnh nên phải rút lui để bảo toàn lực lượng. Vua tôi nhà Trần rời Thăng Long, thực hiện kế \"Vườn không nhà trống\": đem dân, của đi nơi khác, không để giặc cướp được lương thực. Quân Mông Cổ vào Thăng Long chỉ thấy kinh thành trống không, thiếu lương và mệt mỏi."},{"type":"map","lat":21.03,"lng":105.85,"zoom":8,"label":"Thăng Long – Đông Bộ Đầu","caption":"Kinh thành Thăng Long, nơi diễn ra trận phản công cuối cùng."},{"type":"text","heading":"Kết quả và bài học","text":"Ngày 29/1/1258, quân Trần phản công thắng lợi ở Đông Bộ Đầu, quét sạch giặc khỏi bờ cõi. Nhà Trần chọn lui để giữ lực lượng rồi phản công khi thế giặc suy yếu — cách đánh sẽ còn được dùng lại ở hai cuộc kháng chiến sau."}]$j$::jsonb, 4, 'draft', $t$khang chien chong mong co lan thu nhat (1258) vi sao nha tran chon lui de bao toan luc luong roi moi phan cong? boi canh dau nam 1258, khoang 3 van quan mong co do tuong ngot luong hop thai chi huy tien vao dai viet. luc nay nha tran do vua tran thai tong dung dau, thai su tran thu do giup viec trieu chinh. dien bien quan tran chan giac o binh le nguyen nhung the giac manh nen phai rut lui de bao toan luc luong. vua toi nha tran roi thang long, thuc hien ke "vuon khong nha trong": dem dan, cua di noi khac, khong de giac cuop duoc luong thuc. quan mong co vao thang long chi thay kinh thanh trong khong, thieu luong va met moi. kinh thanh thang long, noi dien ra tran phan cong cuoi cung. ket qua va bai hoc ngay 29/1/1258, quan tran phan cong thang loi o dong bo dau, quet sach giac khoi bo coi. nha tran chon lui de giu luc luong roi phan cong khi the giac suy yeu — cach danh se con duoc dung lai o hai cuoc khang chien sau.$t$) RETURNING id INTO new_id;
    ls := ls || jsonb_build_object('l1', new_id);
    VALUES ($t$Kháng chiến chống Nguyên lần thứ hai (1285)$t$, $t$Từ Hội nghị Bình Than đến chiến thắng Chương Dương.$t$, (camp->>'c2')::integer, $j$[{"type":"text","heading":"Chuẩn bị","text":"Trước nguy cơ bị xâm lược, năm 1282 nhà Trần mở Hội nghị Bình Than bàn kế đánh giặc; năm 1283 Trần Quốc Tuấn (Trần Hưng Đạo) được phong Quốc công Tiết chế, thống lĩnh quân đội. Nhà Trần còn mời các bô lão đến Diên Hồng hỏi ý kiến nên đánh hay hòa; tất cả đồng thanh hô \"Đánh!\"."},{"type":"text","heading":"Diễn biến","text":"Đầu năm 1285, Thoát Hoan từ phía Bắc phối hợp Toa Đô từ phía Nam đánh Đại Việt. Quân Trần rút lui bảo toàn lực lượng; Trần Bình Trọng chặn quân Nguyên ở Đà Mạc, bị bắt và hy sinh nhưng không chịu làm vương đất Bắc. Tháng 5 – 6/1285 quân Trần phản công, thắng lớn ở Tây Kết, Hàm Tử và Chương Dương."},{"type":"map","lat":21.03,"lng":105.85,"zoom":8,"label":"Thăng Long","caption":"Thăng Long được giải phóng sau chiến thắng Chương Dương."},{"type":"text","heading":"Kết quả","text":"Thăng Long được giải phóng, Toa Đô bị chém đầu, Thoát Hoan phải tháo chạy về nước, chui vào ống đồng để tránh tên độc của quân dân nhà Trần."}]$j$::jsonb, 5, 'draft', $t$khang chien chong nguyen lan thu hai (1285) tu hoi nghi binh than den chien thang chuong duong. chuan bi truoc nguy co bi xam luoc, nam 1282 nha tran mo hoi nghi binh than ban ke danh giac; nam 1283 tran quoc tuan (tran hung dao) duoc phong quoc cong tiet che, thong linh quan doi. nha tran con moi cac bo lao den dien hong hoi y kien nen danh hay hoa; tat ca dong thanh ho "danh!". dien bien dau nam 1285, thoat hoan tu phia bac phoi hop toa do tu phia nam danh dai viet. quan tran rut lui bao toan luc luong; tran binh trong chan quan nguyen o da mac, bi bat va hy sinh nhung khong chiu lam vuong dat bac. thang 5 – 6/1285 quan tran phan cong, thang lon o tay ket, ham tu va chuong duong. thang long duoc giai phong sau chien thang chuong duong. ket qua thang long duoc giai phong, toa do bi chem dau, thoat hoan phai thao chay ve nuoc, chui vao ong dong de tranh ten doc cua quan dan nha tran.$t$) RETURNING id INTO new_id;
    ls := ls || jsonb_build_object('l2', new_id);
    VALUES ($t$Kháng chiến chống Nguyên lần thứ ba (1287 – 1288)$t$, $t$Vân Đồn cắt lương, Bạch Đằng chôn vùi thủy quân Nguyên.$t$, (camp->>'c3')::integer, $j$[{"type":"text","heading":"Bối cảnh","text":"Cuối năm 1287, Thoát Hoan lại đem quân xâm lược Đại Việt, đi cùng đoàn thuyền lương của Trương Văn Hổ và thủy quân do Ô Mã Nhi chỉ huy. Nhà Trần tiếp tục rút lui bảo toàn lực lượng, chờ thời cơ phản công."},{"type":"text","heading":"Vân Đồn","text":"Đầu năm 1288, Phó đô tướng quân Trần Khánh Dư phục kích ở Vân Đồn, đánh tan đoàn thuyền lương của giặc. Quân Nguyên thiếu lương thực, buộc phải rút khỏi Thăng Long."},{"type":"map","lat":20.95,"lng":106.8,"zoom":9,"label":"Sông Bạch Đằng","caption":"Nơi Trần Hưng Đạo bố trí bãi cọc ngầm."},{"type":"text","heading":"Bạch Đằng","text":"Trần Hưng Đạo cho cắm cọc nhọn dưới lòng sông Bạch Đằng. Tháng 4/1288, khi thủy triều lên, thuyền chiến của Ô Mã Nhi bị nhử vào trận địa; khi nước rút, thuyền va vào cọc và bị đánh tan. Ô Mã Nhi và Phàn Tiếp bị bắt, mộng xâm lăng của nhà Nguyên bị đập tan hoàn toàn."}]$j$::jsonb, 5, 'draft', $t$khang chien chong nguyen lan thu ba (1287 – 1288) van don cat luong, bach dang chon vui thuy quan nguyen. boi canh cuoi nam 1287, thoat hoan lai dem quan xam luoc dai viet, di cung doan thuyen luong cua truong van ho va thuy quan do o ma nhi chi huy. nha tran tiep tuc rut lui bao toan luc luong, cho thoi co phan cong. van don dau nam 1288, pho do tuong quan tran khanh du phuc kich o van don, danh tan doan thuyen luong cua giac. quan nguyen thieu luong thuc, buoc phai rut khoi thang long. noi tran hung dao bo tri bai coc ngam. bach dang tran hung dao cho cam coc nhon duoi long song bach dang. thang 4/1288, khi thuy trieu len, thuyen chien cua o ma nhi bi nhu vao tran dia; khi nuoc rut, thuyen va vao coc va bi danh tan. o ma nhi va phan tiep bi bat, mong xam lang cua nha nguyen bi dap tan hoan toan.$t$) RETURNING id INTO new_id;
    ls := ls || jsonb_build_object('l3', new_id);
    VALUES ('system', NULL, NULL, $t$Hành trình Lần I – Vườn không nhà trống$t$, $t$Từ cuộc xâm lược của quân Mông Cổ đến trận phản công Đông Bộ Đầu.$t$, (camp->>'c1')::integer, 'draft', $t$hanh trinh lan i – vuon khong nha trong tu cuoc xam luoc cua quan mong co den tran phan cong dong bo dau.$t$) RETURNING id INTO journey_id;
    VALUES (journey_id, 1, 'lesson', (SELECT title FROM public.hk_lessons WHERE id = (ls->>'l1')::integer), 'book', (ls->>'l1')::integer, NULL, NULL, NULL, NULL, 50) RETURNING id INTO node_id;
    VALUES (journey_id, 2, 'quiz', $t$Bình Lệ Nguyên và "Vườn không nhà trống"$t$, 'quiz', NULL, (zs->>'z1_binh_le')::integer, NULL, NULL, NULL, 60) RETURNING id INTO node_id;
    VALUES (journey_id, 3, 'battle', (SELECT name FROM public.hist_battles WHERE slug = 'dong-bo-dau'), 'sword', NULL, (zs->>'z1_dong_bo_dau')::integer, NULL, (SELECT id FROM public.hist_battles WHERE slug = 'dong-bo-dau'), NULL, 80) RETURNING id INTO node_id;
    VALUES (journey_id, 4, 'final', $t$Quyết chiến Đông Bộ Đầu$t$, 'crown', NULL, (zs->>'z1_final')::integer, NULL, NULL, 70, 200) RETURNING id INTO node_id;
    VALUES ('system', NULL, NULL, $t$Hành trình Lần II – Hào khí Chương Dương$t$, $t$Từ Hội nghị Bình Than đến cuộc tổng phản công mùa hè 1285.$t$, (camp->>'c2')::integer, 'draft', $t$hanh trinh lan ii – hao khi chuong duong tu hoi nghi binh than den cuoc tong phan cong mua he 1285.$t$) RETURNING id INTO journey_id;
    VALUES (journey_id, 1, 'lesson', (SELECT title FROM public.hk_lessons WHERE id = (ls->>'l2')::integer), 'book', (ls->>'l2')::integer, NULL, NULL, NULL, NULL, 50) RETURNING id INTO node_id;
    VALUES (journey_id, 2, 'quiz', $t$Chuẩn bị kháng chiến và trận Đà Mạc$t$, 'quiz', NULL, (zs->>'z2_da_mac')::integer, NULL, NULL, NULL, 60) RETURNING id INTO node_id;
    VALUES (journey_id, 3, 'battle', (SELECT name FROM public.hist_battles WHERE slug = 'ham-tu'), 'sword', NULL, NULL, NULL, (SELECT id FROM public.hist_battles WHERE slug = 'ham-tu'), NULL, 60) RETURNING id INTO node_id;
